CREATE OR REPLACE FUNCTION public.tms_import_nfe_worker(payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; pair text; nf_id text; r public.app_records%ROWTYPE; oc public.app_records%ROWTYPE; rid text; oid text; v jsonb; now_text text:=now()::text; BEGIN k:=payload->>'chaveNFe'; IF k !~ '^\d{44}$' OR payload->>'xmlOriginal' IS NULL OR regexp_replace((xpath('string(//*[local-name()="infNFe"]/@Id)',xmlparse(document payload->>'xmlOriginal')))[1]::text,'^NFe','') IS DISTINCT FROM k THEN RAISE EXCEPTION 'NF-e inválida'; END IF; pair:=coalesce(payload->>'remetenteCnpj','')||'|'||coalesce(payload->>'destinatarioCnpj',''); PERFORM pg_advisory_xact_lock(hashtextextended('rota:'||pair,0)); PERFORM pg_advisory_xact_lock(hashtextextended('nfe:'||k,0)); IF EXISTS(SELECT 1 FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=k) THEN RETURN jsonb_build_object('status','duplicado'); END IF; nf_id:='ORD-NFE-'||k; SELECT * INTO r FROM public.app_records WHERE collection='rotas' AND data->>'status'='aberta' AND coalesce(data->>'remetenteCnpj','')=coalesce(payload->>'remetenteCnpj','') AND coalesce(data->>'destinatarioCnpj','')=coalesce(payload->>'destinatarioCnpj','') ORDER BY criado_em LIMIT 1 FOR UPDATE; rid:=coalesce(r.id,'ROT-'||gen_random_uuid()::text); v:=coalesce(r.data,jsonb_build_object('id',rid,'clienteId',payload->>'clienteId','clienteNome',payload->>'clienteNome','remetente',payload->>'remetente','remetenteCnpj',payload->>'remetenteCnpj','destinatario',payload->>'destinatario','destinatarioCnpj',payload->>'destinatarioCnpj','cidadeColeta',payload->>'cidadeColeta','ufColeta',payload->>'ufColeta','cidadeEntrega',payload->>'cidadeEntrega','ufEntrega',payload->>'ufEntrega','status','aberta','orderIds','[]'::jsonb,'criadoEm',now_text)); v:=v||jsonb_build_object('orderIds',coalesce(v->'orderIds','[]'::jsonb)||jsonb_build_array(nf_id),'atualizadoEm',now_text); INSERT INTO public.app_records(collection,id,data,version) VALUES('rotas',rid,v,coalesce(r.version,0)+1) ON CONFLICT(collection,id) DO UPDATE SET data=excluded.data,version=excluded.version,atualizado_em=now(); SELECT * INTO oc FROM public.app_records WHERE collection='ordensColeta' AND data->>'rotaId'=rid AND data->>'status' IN('aguardando_programacao','emitida','enviada_motorista') LIMIT 1 FOR UPDATE; oid:=coalesce(oc.id,'OC-'||gen_random_uuid()::text); v:=coalesce(oc.data,jsonb_build_object('id',oid,'numero','OC-'||left(md5(oid),10),'rotaId',rid,'clienteNome',payload->>'clienteNome','localColeta',payload->>'remetente','cidadeColeta',payload->>'cidadeColeta','ufColeta',payload->>'ufColeta','dataHoraColeta','','localEntrega',payload->>'destinatario','cidadeEntrega',payload->>'cidadeEntrega','ufEntrega',payload->>'ufEntrega','dataHoraEntrega','','status','aguardando_programacao','orderIds','[]'::jsonb,'criadoEm',now_text,'criadoPor','automacao')); v:=v||jsonb_build_object('orderIds',coalesce(v->'orderIds','[]'::jsonb)||jsonb_build_array(nf_id),'atualizadoEm',now_text); INSERT INTO public.app_records(collection,id,data,version) VALUES('ordensColeta',oid,v,coalesce(oc.version,0)+1) ON CONFLICT(collection,id) DO UPDATE SET data=excluded.data,version=excluded.version,atualizado_em=now(); INSERT INTO public.app_records(collection,id,data) VALUES('orders',nf_id,payload||jsonb_build_object('id',nf_id,'criadoEm',now_text,'atualizadoEm',now_text)); UPDATE public.email_xml_inbox SET status='importado',importado_em=now(),motivo_pendencia=NULL WHERE chave=k AND tipo='nfe'; RETURN jsonb_build_object('status','importado','rota',rid,'oc',oid); END $$;
REVOKE ALL ON FUNCTION public.tms_import_nfe_worker(jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.tms_import_nfe_worker(jsonb) TO service_role;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.tms_import_cte(text)'::regprocedure) INTO definition; definition:=replace(definition, 'IF NOT public.tms_module(''/coletas'') THEN', 'IF coalesce(auth.role(),'''')<>''service_role'' AND NOT public.tms_module(''/coletas'') THEN'); EXECUTE definition; END $$;
GRANT EXECUTE ON FUNCTION public.tms_import_cte(text) TO service_role;